insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('29e4ad7c-c74c-56b0-9713-a6206f2c44ec', 'Energy is lost at each transfer, so only about 10% passes on [1]; most is lost as heat from respiration, and in uneaten or undigested material [1]; after four or five levels there is too little energy left to support another population [1].', 'Energy is lost at each transfer, so only about 10% passes on [1]; most is lost as heat from respiration, and in uneaten or undigested material [1]; after four or five levels there is too little energy left to support another population [1].', '[{"text": "Marking point 1", "any": ["lost", "loss", "10%", "only a small"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["respiration", "heat"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["not enough energy", "too little", "cannot support"], "all": [], "marks": 1}]'::jsonb, 'Energy is lost at each transfer, so only about 10% passes on [1]; most is lost as heat from respiration, and in uneaten or undigested material [1]; after four or five levels there is too little energy left to support another population [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
