insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1adb7621-d73c-559b-806a-54e56a4076b3', 'Energy flows one way through ecosystems and is eventually lost as heat [1]; chemical elements are recycled, returned to the environment by decomposers and reused [1].', 'Energy flows one way through ecosystems and is eventually lost as heat [1]; chemical elements are recycled, returned to the environment by decomposers and reused [1].', '[{"text": "Marking point 1", "any": ["one direction", "lost as heat", "not recycled"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["recycled", "cycle", "decomposers"], "all": [], "marks": 1}]'::jsonb, 'Energy flows one way through ecosystems and is eventually lost as heat [1]; chemical elements are recycled, returned to the environment by decomposers and reused [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
