insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('37db0dbe-a76a-56dd-94bf-e52ab87e9787', 'Bacteria reproduce asexually, so they do not interbreed [1]; they exchange genes by horizontal gene transfer (e.g. plasmids) between different types, blurring species boundaries [1].', 'Bacteria reproduce asexually, so they do not interbreed [1]; they exchange genes by horizontal gene transfer (e.g. plasmids) between different types, blurring species boundaries [1].', '[{"text": "Marking point 1", "any": ["asexual", "do not interbreed", "binary fission"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["horizontal", "plasmid", "exchange genes", "gene transfer"], "all": [], "marks": 1}]'::jsonb, 'Bacteria reproduce asexually, so they do not interbreed [1]; they exchange genes by horizontal gene transfer (e.g. plasmids) between different types, blurring species boundaries [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
