insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ecc3ef28-42d8-5046-84d4-13b6030c2770', 'short', 'Explain why horses and donkeys are classified as separate species.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Equidae_E._africanus_asinus_x_E._ferus_caballus_(Mule).jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ecc3ef28-42d8-5046-84d4-13b6030c2770', 'Horses and donkeys can interbreed to produce mules [1], but mules are sterile, so the parents do not produce fertile offspring and are separate species [1].', 'Horses and donkeys can interbreed to produce mules [1], but mules are sterile, so the parents do not produce fertile offspring and are separate species [1].', '[{"text": "Marking point 1", "any": ["mule", "offspring", "hybrid"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["sterile", "infertile", "not fertile"], "all": [], "marks": 1}]'::jsonb, 'Horses and donkeys can interbreed to produce mules [1], but mules are sterile, so the parents do not produce fertile offspring and are separate species [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('f8df87e8-23d4-5c80-a5bf-11843c11f886', 'ecc3ef28-42d8-5046-84d4-13b6030c2770', 5);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5610f6bd-c181-505e-95dc-cc7a44e3b92a', 'short', 'Explain why it can be difficult to decide whether two populations are separate species.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Equidae_E._africanus_asinus_x_E._ferus_caballus_(Mule).jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5610f6bd-c181-505e-95dc-cc7a44e3b92a', 'Populations that are separated stop interbreeding and diverge gradually during speciation [1]; there is no clear point at which they become separate species, and if they never meet we cannot test whether they can interbreed [1].', 'Populations that are separated stop interbreeding and diverge gradually during speciation [1]; there is no clear point at which they become separate species, and if they never meet we cannot test whether they can interbreed [1].', '[{"text": "Marking point 1", "any": ["gradual", "diverge", "speciation", "continuous"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["do not meet", "not interbreed", "isolated", "cannot test", "no clear point"], "all": [], "marks": 1}]'::jsonb, 'Populations that are separated stop interbreeding and diverge gradually during speciation [1]; there is no clear point at which they become separate species, and if they never meet we cannot test whether they can interbreed [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
